            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Nouvelles-R&#232;gles-Sur-Les-Apparitions.html&quot; title=&quot;Nouvelles r&#232;gles sur les apparitions&quot;&gt;Les nouvelles r&#232;gles sur les apparitions&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Les-Lignes-Telluriques.html&quot; title=&quot;Les lignes telluriques&quot;&gt;Les lignes telluriques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Paysages-Mentaux.html&quot; title=&quot;Les paysages mentaux&quot;&gt;Les paysages mentaux&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Plans-&#201;sot&#233;riques.html&quot; title=&quot;Plans &#233;sot&#233;riques&quot;&gt;Les plans &#233;sot&#233;riques&lt;/a&gt;&lt;/li&gt;
        &lt;/ul&gt;
    &lt;/li&gt;
    &lt;li&gt;&lt;div style=&quot;float: right; padding: 0;&quot;&gt;
&lt;IMG id=&quot;bouton2&quot; src=&quot;/images/pathfinder/wiki/BoutonP.jpg&quot; style=&quot;float:right; width: 10px; border: 1px solid black; cursor: pointer&quot; onmouseover=&quot;overButton(&#39;2&#39;);&quot; onmouseout=&quot;outButton(&#39;2&#39;);&quot; onclick=&quot;expandMenu(&#39;2&#39;);&quot; /&gt;
&lt;/div&gt;R&#232;gles techniques&amp;emsp;
        &lt;ul ID=&quot;2&quot; CLASS=&quot;listecach&#233;e cadrebas&quot;&gt;
